const packGroups=[['证件 / 入境',[['passport','两人护照原件','建议有效期至少余 6 个月；核对姓名与机票完全一致。'],['identity','身份证备用','深圳出发及国内身份核验备用，不能用来代替护照出境泰国。'],['permit','港澳通行证：如已有可备','此次按护照经港往返泰国的第三地过境规则，不把通行证或旅游签注列为必办。'],['ticket','往返电子客票与行程单','保存离线截图；10/7 02:00 是曼谷出发时间。'],['hotel','酒店确认单与英文地址','TDAC 要用首晚地址；保存前台电话与取消期限。'],['tdac','9/30–10/1 完成两人 TDAC','每个人都有确认件，姓名/证件号码核对无误。'],['insurance','旅行保险与资金材料','确认医疗、延误、海上活动保障和境外援助；资金标准按实际入境类别核实。']]],['预订 / 手机',[['transfer','深圳湾机场班车确认','了解深圳湾机场直达服务和 T2 下车点即可；具体公司、乘车方式和班次自行选择。'],['pattaya','芭提雅大巴与演出确认','5 日上午去、6 日上午至中午回；5 日住芭提雅，演出后不赶车。'],['massage','按摩门店与两人时段确认','券限定门店，提前预约，安排在 10/3–10/4 空闲时段，不挤进返程日。'],['apps','Google Maps / Grab / 翻译','提前登录，下载离线地图；境外网络实际可用。'],['sim','漫游或 eSIM / 电话卡','核对手机兼容性，保留国内号码接验证码。'],['pay','银行卡＋适量现金','核对境外额度、结算币种、PIN；现金分开放。']]],['随身包',[['power','手机、充电线、插头、充电宝','充电宝随身，查航司容量/数量规定；带转换插头。'],['rain','小伞、薄外套、防水袋','飞机和商场冷，十月有阵雨。'],['care','防晒、防蚊、纸巾、湿巾','选择适合自己的用品，防晒按标签使用。'],['med','常用药与处方记录','保留原包装；含受管制成分药物先查泰国携药要求。'],['bag','水瓶、小额零钱、安全小包','贵重物品随身，不挂在椅背或交陌生人保管。']]],['托运行李 / 出门前',[['clothes','轻薄换洗衣物与寺庙长装','按天气穿搭清单，过膝、不透、有袖。'],['shoes','防滑鞋＋快干凉鞋','别只带新鞋和高跟鞋。'],['weight','称重：每人手提 7kg、托运 23kg','以所附订单及航司最新限制为准，液体整理到对应行李。'],['alarm','10/1 晚设手机闹钟','10/2 早上大致 06:30–07:00 出门，闹钟自行决定；10/6 晚去 BKK 另设提醒。'],['offline','保存本页 PDF 与订单','网页地图需要网络，不能只依赖在线页面。']]]];
let checked={};try{checked=JSON.parse(localStorage.getItem('trip-prep-v1')||'{}');if(!checked||typeof checked!=='object'||Array.isArray(checked))checked={};}catch{checked={};document.getElementById('storage-note').textContent='当前浏览器无法读取保存状态；清单仍可使用，但勾选可能不会保留。';}
function saveCheck(key,value){if(!packGroups.some(g=>g[1].some(x=>x[0]===key))||typeof value!=='boolean')throw Error('无效清单项');checked[key]=value;try{localStorage.setItem('trip-prep-v1',JSON.stringify(checked));}catch{document.getElementById('storage-note').textContent='浏览器禁止保存，当前勾选仅本次打开有效。';}const input=document.querySelector('[data-pack="'+key+'"]');if(input)input.checked=value;updateProgress();return{item:key,checked:value};}
function updateProgress(){const items=packGroups.flatMap(g=>g[1]);document.getElementById('pack-progress').textContent=items.filter(x=>checked[x[0]]===true).length+' / '+items.length+' 项已准备';}
packGroups.forEach(([title,items])=>{const card=document.createElement('div');card.className='card';const h=document.createElement('h3');h.textContent=title;card.append(h);items.forEach(([key,title,desc])=>{const label=document.createElement('label');label.className='pack-item';const input=document.createElement('input');input.type='checkbox';input.dataset.pack=key;input.checked=checked[key]===true;input.addEventListener('change',()=>saveCheck(key,input.checked));const span=document.createElement('span');const strong=document.createElement('strong');strong.textContent=title;const small=document.createElement('small');small.textContent=desc;span.append(strong,small);label.append(input,span);card.append(label);});document.getElementById('packing-list').append(card);});updateProgress();
function dateInZone(now,zone){return new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(now);}
function autoDay(){const now=new Date();const z=now>=new Date('2026-10-02T14:55:00+07:00')&&now<new Date('2026-10-07T05:55:00+08:00')?'Asia/Bangkok':'Asia/Shanghai';const date=dateInZone(now,z);return agenda[date]?date:(date<'2026-10-02'?'prep':'2026-10-07');}
let selectedDay=autoDay();const selector=document.getElementById('day-select');selector.value=selectedDay;
function duration(ms){const minutes=Math.max(0,Math.ceil(ms/60000));return (minutes>=1440?Math.floor(minutes/1440)+' 天 ':'')+Math.floor(minutes%1440/60)+' 小时 '+minutes%60+' 分钟';}
function selectDay(key){if(!Object.hasOwn(agenda,key))throw Error('无效日期');selectedDay=key;selector.value=key;renderDashboard();return {date:key,events:agenda[key].events.length};}
function renderDashboard(){const now=new Date(),a=agenda[selectedDay];const actual=autoDay();document.getElementById('live-clock').textContent='深圳/香港 '+now.toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false,month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})+' · 泰国 '+now.toLocaleTimeString('zh-CN',{timeZone:'Asia/Bangkok',hour12:false,hour:'2-digit',minute:'2-digit'});const next=a.events.find(x=>x[0]&&new Date(x[0])>now);document.getElementById('view-mode').textContent=selectedDay==='prep'?'出发前准备':selectedDay===actual?'当前日期安排':'正在预览 '+selectedDay+'（不是今天）';document.getElementById('next-title').textContent=next?next[2]:(a.events.every(x=>!x[0])?'当天自由安排':'当天计划时间已过');document.getElementById('countdown').textContent=next?'距离 '+next[1]+' 还有 '+duration(new Date(next[0])-now):(a.events.every(x=>!x[0])?'游玩时段仅供参考，不设逐项倒计时。':'时间经过不等于已完成，请自行核对行程。');document.getElementById('next-note').textContent=next?next[3]:'可切换日期查看其他安排。';const list=document.getElementById('daily-timeline');list.replaceChildren();a.events.forEach(x=>{const row=document.createElement('a');row.className='timeline-node'+(x===next?' upcoming':'');row.href=x[4];if(x[4].startsWith('http')){row.target='_blank';row.rel='noreferrer';}const time=document.createElement('time');if(x[0])time.dateTime=x[0];time.textContent=x[1];const title=document.createElement('strong');title.textContent=x[2];const small=document.createElement('small');small.textContent=x[3];row.append(time,title,small);list.append(row);});const bag=document.getElementById('daily-bag');bag.replaceChildren();a.bag.forEach(t=>{const p=document.createElement('p');p.textContent='□ '+t;bag.append(p);});document.getElementById('daily-money').textContent=a.money;document.getElementById('tomorrow-note').textContent=a.next;document.getElementById('daily-map-link').onclick=()=>renderRoute(a.route);}
selector.addEventListener('change',()=>selectDay(selector.value));document.getElementById('back-today').addEventListener('click',()=>selectDay(autoDay()));renderDashboard();setInterval(renderDashboard,60000);
function revealAnchor(){const id=decodeURIComponent(location.hash.slice(1));if(!id)return;const el=document.getElementById(id);if(el){const details=el.querySelector(':scope > details.guide-fold');if(details)details.open=true;requestAnimationFrame(()=>el.scrollIntoView());}}
window.addEventListener('hashchange',revealAnchor);document.addEventListener('click',ev=>{const a=ev.target.closest('a[href^="#"]');if(a){const el=document.getElementById(a.getAttribute('href').slice(1));const d=el?.querySelector(':scope > details.guide-fold');if(d)d.open=true;}});revealAnchor();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const t of [{name:'select_trip_day',title:'查看行程日期',description:'切换首页显示日期，不改变预订或行程内容。',inputSchema:{type:'object',properties:{date:{type:'string',enum:Object.keys(agenda)}},required:['date'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).some(x=>x!=='date'))throw Error('参数无效');return selectDay(input.date);}},{name:'set_packing_item_checked',title:'更新本机准备清单',description:'更新当前浏览器的准备勾选，不预订、不上传证件、不跨设备同步。',inputSchema:{type:'object',properties:{item:{type:'string',enum:packGroups.flatMap(g=>g[1].map(x=>x[0]))},checked:{type:'boolean'}},required:['item','checked'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).some(x=>!['item','checked'].includes(x)))throw Error('参数无效');return saveCheck(input.item,input.checked);}}]){try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
